/**
 * Scratch page for T2 — renders every atlas frame, labelled, so the slicer's output can
 * be eyeballed against the original sheet. Not part of the game; served at /atlas.html.
 *
 * H3 made it the review surface for the HD set: both sheets are loaded and **H** swaps
 * every sprite between them in place. A live swap is the point — a silhouette that has
 * gone subtly wrong is very hard to see in isolation and impossible to miss when it
 * moves. `?hd=0` picks which one the page opens on.
 */
import { Application, Container, Graphics, Sprite, Text, type Spritesheet } from 'pixi.js';

import { hdEnabled, loadSheet } from './sheet.ts';

const ZOOM = 3;
const CELL_W = 112;
const CELL_H = 172; // tall enough for the 24x48 door strip at ZOOM
const COLUMNS = 12;

async function main(): Promise<void> {
  const canvas = document.getElementById('atlas-canvas') as HTMLCanvasElement;
  const app = new Application();
  await app.init({ canvas, background: 0x202028, resizeTo: window, antialias: false });

  // Both sheets, same frame names, same logical frame sizes — `meta.scale` is what makes
  // the HD one 12x12 logical over 96x96 texels, so the grid below does not move.
  const sheets: Record<'sd' | 'hd', Spritesheet> = {
    sd: await loadSheet(false),
    hd: await loadSheet(true),
  };
  let hd = hdEnabled();
  const sheet = (): Spritesheet => (hd ? sheets.hd : sheets.sd);

  const root = new Container();
  app.stage.addChild(root);

  const names = Object.keys(sheets.sd.textures);
  /** Every frame's sprite, so the toggle can re-texture them without a rebuild. */
  const sprites = new Map<string, Sprite>();

  names.forEach((name, index) => {
    const column = index % COLUMNS;
    const row = Math.floor(index / COLUMNS);
    const cell = new Container();
    cell.position.set(column * CELL_W + 8, row * CELL_H + 8);

    const texture = sheet().textures[name]!;
    const sprite = new Sprite(texture);
    sprite.scale.set(ZOOM);
    sprites.set(name, sprite);

    // A checker plate behind the sprite so transparent pixels are obvious.
    const plate = new Graphics();
    for (let y = 0; y < sprite.height; y += 8) {
      for (let x = 0; x < sprite.width; x += 8) {
        plate.rect(x, y, 8, 8).fill((x / 8 + y / 8) % 2 === 0 ? 0x3a3a44 : 0x2c2c34);
      }
    }
    cell.addChild(plate, sprite);

    const label = new Text({
      text: name,
      style: { fill: 0xd0d0d8, fontFamily: 'monospace', fontSize: 9 },
    });
    label.position.set(0, sprite.height + 2);
    cell.addChild(label);

    const size = new Text({
      text: `${texture.width}x${texture.height}`,
      style: { fill: 0x7a7a88, fontFamily: 'monospace', fontSize: 9 },
    });
    size.position.set(0, sprite.height + 13);
    cell.addChild(size);

    root.addChild(cell);
  });

  const heading = new Text({
    text: '',
    style: { fill: 0xffffff, fontFamily: 'monospace', fontSize: 12 },
  });
  root.addChild(heading);
  root.children.forEach((child) => {
    if (child !== heading) child.y += 20;
  });

  function apply(): void {
    const active = sheet();
    for (const [name, sprite] of sprites) sprite.texture = active.textures[name]!;
    const density = active.textureSource.resolution;
    heading.text = `${names.length} frames — ${hd ? 'HD' : 'SD'} (${density}x texels, ${
      active.textureSource.scaleMode
    }) — H to toggle`;
  }
  apply();

  window.addEventListener('keydown', (event) => {
    if (event.key.toLowerCase() !== 'h') return;
    hd = !hd;
    apply();
  });

  // The grid is taller than the window; scroll it with the wheel.
  window.addEventListener('wheel', (event) => {
    const rows = Math.ceil(names.length / COLUMNS);
    const maxScroll = Math.max(0, rows * CELL_H + 40 - window.innerHeight);
    root.y = Math.min(0, Math.max(-maxScroll, root.y - event.deltaY));
  });
}

void main();
